def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    average = sum(values) / len(values)
    return {
        "value": average,
        "trace": {
            "values": values,
            "count": len(values),
            "average": average,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"}
        }
    }
